"""How many diameter-1 regular hexagons of a honeycomb meet T_6?  (float scan)"""
import math, sys
from search import triangle, clip

SQ3 = math.sqrt(3.0)

def area(poly):
    s = 0.0
    for i in range(len(poly)):
        x1, y1 = poly[i]; x2, y2 = poly[(i+1) % len(poly)]
        s += x1*y2 - x2*y1
    return abs(s)/2.0

def count(a, th, ox, oy):
    tri = triangle(a)
    # hexagon centre lattice: spacing sqrt3/2, generated by rotating (3/4,+-sqrt3/4)
    c, s = math.cos(th), math.sin(th)
    def rot(p): return (c*p[0]-s*p[1], s*p[0]+c*p[1])
    g1 = rot((0.75, SQ3/4)); g2 = rot((0.75, -SQ3/4))
    hexv = [rot((0.5*math.cos(k*math.pi/3), 0.5*math.sin(k*math.pi/3))) for k in range(6)]
    R = int(a/0.4)+4
    n = 0
    tot = 0.0
    for i in range(-R, R+1):
        for j in range(-R, R+1):
            cx = ox + i*g1[0] + j*g2[0]; cy = oy + i*g1[1] + j*g2[1]
            if not (-1.5 <= cx <= a+1.5 and -1.5 <= cy <= a*SQ3/2+1.5):
                continue
            poly = [(cx+vx, cy+vy) for vx, vy in hexv]
            p = poly
            for k in range(3):
                x1, y1 = tri[k]; x2, y2 = tri[(k+1)%3]
                nx, ny = (y2-y1), -(x2-x1)
                # inward test with third vertex
                x3, y3 = tri[(k+2)%3]
                cc = nx*x1+ny*y1
                if nx*x3+ny*y3 > cc: nx, ny, cc = -nx, -ny, -cc
                p = clip(p, nx, ny, cc)
                if not p: break
            if p and area(p) > 1e-12:
                n += 1
                tot += area(p)
    return n, tot

if __name__ == "__main__":
    a = float(sys.argv[1])
    best = (10**9, None)
    M = 24
    for ti in range(M):
        th = ti*math.pi/3/M
        for oi in range(14):
            for oj in range(14):
                ox = oi*0.75/14*2; oy = oj*SQ3/4/14*2
                n, tot = count(a, th, ox, oy)
                if n < best[0]:
                    best = (n, (th, ox, oy, tot))
    print("a=%g  min hexagons meeting T_a = %d  at theta=%.5f off=(%.4f,%.4f) covered-area=%.4f"
          % (a, best[0], best[1][0], best[1][1], best[1][2], best[1][3]))
